import io.netty.bootstrap.Bootstrap;
import io.netty.bootstrap.ServerBootstrap;
import io.netty.buffer.ByteBuf;
import io.netty.buffer.Unpooled;
import io.netty.channel.*;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.SocketChannel;
import io.netty.channel.socket.nio.NioServerSocketChannel;
import io.netty.channel.socket.nio.NioSocketChannel;

import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * The Blynk Project.
 * Created by Dmitriy Dumanskiy.
 * Created on 01.02.16.
 */
public class Reregister {


    private static final AtomicInteger i = new AtomicInteger();
    private static final Map<Integer, EventLoop> users = new ConcurrentHashMap<>();

    public static void main(String[] args) throws Exception {
        EventLoopGroup boss = new NioEventLoopGroup(1);
        EventLoopGroup worker = new NioEventLoopGroup(100);

        new Reregister().buildServerAndRun(boss, worker, NioServerSocketChannel.class);
        new Client().connect();
        Thread.sleep(100);
        new Client().connect().send();
    }

    private void buildServerAndRun(EventLoopGroup bossGroup, EventLoopGroup workerGroup,
                                   Class<? extends ServerChannel> channelClass) throws Exception {
        ServerBootstrap b = new ServerBootstrap();
        b.group(bossGroup, workerGroup)
                .channel(channelClass)
                .childOption(ChannelOption.SO_KEEPALIVE, true)
                .childHandler(getChannelInitializer());

        b.bind(8080).sync();
    }

    protected ChannelInitializer<SocketChannel> getChannelInitializer() {
        return new ChannelInitializer<SocketChannel>() {
            @Override
            protected void initChannel(SocketChannel ch) throws Exception {
                ChannelPipeline pipeline = ch.pipeline();
                pipeline.addLast(
                        new SimpleChannelInboundHandler<ByteBuf>() {
                            @Override
                            protected void channelRead0(ChannelHandlerContext ctx, ByteBuf byteBuf) throws Exception {
                                System.out.println("Retrieved message from " + ctx.channel());
                            }

                            @Override
                            public void channelActive(ChannelHandlerContext ctx) throws Exception {
                                System.out.println("Server: channel active. Channel : " + ctx.channel());

                                EventLoop eventLoop = users.get(i.get());
                                if (eventLoop == null) {
                                    System.out.println("Server: Creating new user " + ctx.channel().eventLoop());
                                    users.put(i.incrementAndGet(), ctx.channel().eventLoop());
                                } else {
                                    System.out.println("Server: Re register from " + ctx.channel().eventLoop() + " to " + eventLoop);
                                    reRegisterChannel(ctx, eventLoop, channelFuture -> completeLogin());
                                }
                            }
                        }
                );
            }
        };
    }

    private static void completeLogin() {
        System.out.println("Complete re register.");
    }

    private static void reRegisterChannel(ChannelHandlerContext ctx, EventLoop eventLoop, ChannelFutureListener completeHandler) {
        ChannelFuture cf = ctx.deregister();
        cf.addListener(new ChannelFutureListener() {
            @Override
            public void operationComplete(ChannelFuture channelFuture) throws Exception {
                eventLoop.register(channelFuture.channel()).addListener(completeHandler);
            }
        });
    }

    private static class Client {

        private Channel channel;

        public Client connect() throws Exception {
            EventLoopGroup group = new NioEventLoopGroup();

            Bootstrap bootstrap = new Bootstrap();
            bootstrap.group(group).channel(NioSocketChannel.class);
            ChannelFuture future = bootstrap
                    .handler(new SimpleChannelInboundHandler<ByteBuf>() {
                        @Override
                        protected void channelRead0(ChannelHandlerContext ctx, ByteBuf byteBuf) throws Exception {

                        }
                    })
                    .connect(new InetSocketAddress("localhost", 8080));

            this.channel = future.sync().channel();
            return this;
        }

        public Client send() {
            channel.writeAndFlush(Unpooled.wrappedBuffer(ByteBuffer.allocate(1).array()));
            return this;
        }
    }

}
