import io.netty.bootstrap.Bootstrap;
import io.netty.bootstrap.ServerBootstrap;
import io.netty.buffer.ByteBuf;
import io.netty.buffer.Unpooled;
import io.netty.channel.*;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.SocketChannel;
import io.netty.channel.socket.nio.NioServerSocketChannel;
import io.netty.channel.socket.nio.NioSocketChannel;
import io.netty.handler.codec.http.*;
import io.netty.util.ReferenceCountUtil;

import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

import static io.netty.handler.codec.http.HttpResponseStatus.OK;
import static io.netty.handler.codec.http.HttpVersion.HTTP_1_1;

/**
 * The Blynk Project.
 * Created by Dmitriy Dumanskiy.
 * Created on 01.02.16.
 */
public class Reregister {


    private static final AtomicInteger i = new AtomicInteger();
    private static final Map<Integer, EventLoop> users = new ConcurrentHashMap<>();

    public static void main(String[] args) throws Exception {
        EventLoopGroup boss = new NioEventLoopGroup(1);
        EventLoopGroup worker = new NioEventLoopGroup(100);

        Reregister reregister = new Reregister();
        reregister.buildServerAndRun(boss, worker, NioServerSocketChannel.class, 8080, reregister.getTCPChannelInitializer());
        reregister.buildServerAndRun(boss, worker, NioServerSocketChannel.class, 8181, reregister.getHTTPChannelInitializer());
        new TCPClient(8080).connect();
        Thread.sleep(100);
        new TCPClient(8080).connect().send();
        Thread.sleep(100);
        new HTTPClient(8181).connect().send();
    }

    private void buildServerAndRun(EventLoopGroup bossGroup, EventLoopGroup workerGroup,
                                   Class<? extends ServerChannel> channelClass, int port, ChannelHandler channelHandler) throws Exception {
        ServerBootstrap b = new ServerBootstrap();
        b.group(bossGroup, workerGroup)
                .channel(channelClass)
                .childOption(ChannelOption.SO_KEEPALIVE, true)
                .childHandler(channelHandler);

        b.bind(port).sync();
    }

    public ChannelInitializer<SocketChannel> getTCPChannelInitializer() {
        return new ChannelInitializer<SocketChannel>() {
            @Override
            protected void initChannel(SocketChannel ch) throws Exception {
                ChannelPipeline pipeline = ch.pipeline();
                pipeline.addLast(
                        new SimpleChannelInboundHandler<ByteBuf>() {
                            @Override
                            protected void channelRead0(ChannelHandlerContext ctx, ByteBuf byteBuf) throws Exception {
                                System.out.println("Retrieved message from " + ctx.channel());
                            }

                            @Override
                            public void channelActive(ChannelHandlerContext ctx) throws Exception {
                                System.out.println("Server: channel active. Channel : " + ctx.channel());

                                EventLoop eventLoop = users.get(i.get());
                                if (eventLoop == null) {
                                    System.out.println("Server: Creating new user " + ctx.channel().eventLoop());
                                    users.put(i.incrementAndGet(), ctx.channel().eventLoop());
                                } else {
                                    System.out.println("Server: Re register from " + ctx.channel().eventLoop() + " to " + eventLoop);
                                    reRegisterChannel(ctx, eventLoop, channelFuture -> completeLoginTCP(channelFuture.channel()));
                                }
                            }
                        }
                );
            }
        };
    }

    public ChannelInitializer<SocketChannel> getHTTPChannelInitializer() {
        return new ChannelInitializer<SocketChannel>() {
            @Override
            protected void initChannel(SocketChannel ch) throws Exception {
                ChannelPipeline pipeline = ch.pipeline();
                pipeline.addLast(
                        new HttpServerCodec(200, 200, 1024),
                        new HttpObjectAggregator(1024, true),
                        new ChannelInboundHandlerAdapter() {
                            @Override
                            public void channelRead(ChannelHandlerContext ctx, Object msg) throws Exception {
                                if (!(msg instanceof HttpRequest)) {
                                    return;
                                }

                                HttpRequest req = (HttpRequest) msg;

                                try {
                                    System.out.println("HTTP Server: got request. Channel : " + ctx.channel());

                                    EventLoop eventLoop = users.get(i.get());
                                    if (eventLoop == null) {
                                        System.out.println("HTTP Server: Creating new user " + ctx.channel().eventLoop());
                                        users.put(i.incrementAndGet(), ctx.channel().eventLoop());
                                    } else {
                                        System.out.println("HTTP Server: Re register from " + ctx.channel().eventLoop() + " to " + eventLoop);
                                        reRegisterChannel(ctx, eventLoop, channelFuture -> completeLoginHTTP(channelFuture.channel()));
                                    }

                                } finally {
                                    ReferenceCountUtil.release(msg);
                                }
                            }
                        }
                );

            }
        };
    }


    private void completeLoginTCP(Channel channel) {
        channel.writeAndFlush(Unpooled.wrappedBuffer(ByteBuffer.allocate(1).array()));
        System.out.println("Complete TCP re register.");
    }

    private void completeLoginHTTP(Channel channel) {
        channel.writeAndFlush(new DefaultFullHttpResponse(HTTP_1_1, OK));
        System.out.println("Complete HTTP re register.");
    }

    private static void reRegisterChannel(ChannelHandlerContext ctx, EventLoop eventLoop, ChannelFutureListener completeHandler) {
        ChannelFuture cf = ctx.deregister();
        cf.addListener(new ChannelFutureListener() {
            @Override
            public void operationComplete(ChannelFuture channelFuture) throws Exception {
                eventLoop.register(channelFuture.channel()).addListener(completeHandler);
            }
        });
    }

    private static class TCPClient {

        private Channel channel;
        private int port;

        public TCPClient(int port) {
            this.port = port;
        }

        public TCPClient connect() throws Exception {
            EventLoopGroup group = new NioEventLoopGroup();

            Bootstrap bootstrap = new Bootstrap();
            bootstrap.group(group).channel(NioSocketChannel.class);
            ChannelFuture future = bootstrap
                    .handler(new SimpleChannelInboundHandler<ByteBuf>() {
                        @Override
                        protected void channelRead0(ChannelHandlerContext ctx, ByteBuf byteBuf) throws Exception {
                            System.out.println("TCP HERE");
                        }
                    })
                    .connect(new InetSocketAddress("localhost", port));

            this.channel = future.sync().channel();
            return this;
        }

        public TCPClient send() {
            channel.writeAndFlush(Unpooled.wrappedBuffer(ByteBuffer.allocate(1).array()));
            return this;
        }
    }

    private static class HTTPClient {

        private Channel channel;
        private int port;

        public HTTPClient(int port) {
            this.port = port;
        }

        public HTTPClient connect() throws Exception {
            EventLoopGroup group = new NioEventLoopGroup();

            Bootstrap bootstrap = new Bootstrap();
            bootstrap.group(group).channel(NioSocketChannel.class);
            ChannelFuture future = bootstrap
                    .handler(getHttpPipeline())
                    .connect(new InetSocketAddress("localhost", port));

            this.channel = future.sync().channel();
            return this;
        }

        private  ChannelInitializer<SocketChannel> getHttpPipeline() {
            return new ChannelInitializer<SocketChannel>() {
                @Override
                protected void initChannel(SocketChannel ch) throws Exception {
                    ChannelPipeline p = ch.pipeline();
                    p.addLast(new HttpClientCodec());
                    p.addLast(new SimpleChannelInboundHandler<HttpObject>() {
                        @Override
                        protected void channelRead0(ChannelHandlerContext ctx, HttpObject msg) throws Exception {
                            System.out.println("HTTP HERE");
                        }
                    });
                }
            };
        }

        public HTTPClient send() {
            HttpRequest request = new DefaultFullHttpRequest(
                    HttpVersion.HTTP_1_1, HttpMethod.GET, "http://localhost:" + port + "/aaa");
            channel.writeAndFlush(request);
            return this;
        }
    }
}
